function renderLessons(){let html='';for(const t of tracks){html+=`<div class="track-title">${t.name}<span>${t.items.length} MODULES</span></div>`;t.items.forEach(item=>{const i=lessons.findIndex(l=>l.title===item[0]),done=state.lessons.includes(i);html+=`<div class="lesson-row" data-lesson="${i}"><div class="lesson-num ${done?'done':''}">${done?'✓':String(i+1).padStart(2,'0')}</div><div class="lesson-info"><b>${item[0]}</b><small>${item[1]}</small></div><span class="lesson-duration">STUDY + APPLY</span><span class="lesson-arrow">→</span></div>`})}$('#lessonList').innerHTML=html;$$('[data-lesson]').forEach(el=>el.onclick=()=>openLesson(+el.dataset.lesson))}
